#!/usr/bin/env python3
"""Generate Soong/Make glue for the stock files listed in proprietary-files.txt.

    setup_makefiles.py <vendor_dir>

Reads  <vendor_dir>/proprietary-files.txt
Writes <vendor_dir>/Android.bp              prebuilt modules (apps, jars, native libs, symlinks)
       <vendor_dir>/vantage-vendor.mk       PRODUCT_PACKAGES / PRODUCT_COPY_FILES

Only module definitions are generated; the binaries stay under <vendor_dir>/proprietary/,
which is populated by scripts/extract-firmware.sh and is never committed.
"""
import re
import hashlib
import sys
from pathlib import Path

OWNER = "motorola"
PART_FLAG = {"system_ext": "system_ext_specific: true,", "product": "product_specific: true,", "system": ""}
COPY_OUT = {"system": "$(TARGET_COPY_OUT_SYSTEM)", "system_ext": "$(TARGET_COPY_OUT_SYSTEM_EXT)",
            "product": "$(TARGET_COPY_OUT_PRODUCT)"}
HEADER = "// Generated by scripts/setup_makefiles.py from proprietary-files.txt. Do not edit.\n"
# LineageOS builds open-source Qualcomm modules with the stock names ims-ext-common,
# qti-telephony-utils (vendor/codeaurora/telephony) and libaudiohalvendorextn
# (vendor/qcom/opensource/commonsys/audio). Every prebuilt here is "prefer: true", so the stock
# file replaces such a source module (Soong's prebuilt selection also looks into the root
# namespace) instead of both installing to the same path.
#
# Their permission files cannot be replaced that way (prebuilt_etc is not a prebuilt module),
# and Soong writes install rules for them whether the product asks for them or not, so a copy to
# the same path would clash. Where the tree's file is byte-identical to the pinned stock file,
# the tree module is installed instead of a copy; the SHA-256 is checked whenever the tree is
# present (inside the source tree), and a difference stops the generation.
TREE_EQUIVALENTS = {
    "product/etc/permissions/ims_ext_common.xml":
        ("ims_ext_common.xml", "vendor/codeaurora/telephony/ims/ims-ext-common/ims_ext_common.xml"),
    "system_ext/etc/permissions/qti_telephony_utils.xml":
        ("qti_telephony_utils.xml", "vendor/codeaurora/telephony/qti-utils/qti_telephony_utils.xml"),
}


# Stock files installed as a module of the same name as a LineageOS module that the product
# disables (patches/vendor/apn: lineage_apn.use_device_apns, set in vantage.mk).
NAMED_MODULES = {
    "product/etc/apns-conf.xml": "apns-conf.xml",
}


def tree_equivalent(vdir, rel, sha):
    """Return the tree module to install instead of copying `rel`, or None."""
    if rel not in TREE_EQUIVALENTS:
        return None
    module, tree_rel = TREE_EQUIVALENTS[rel]
    top = vdir.resolve().parents[2]  # <top>/vendor/motorola/vantage
    tree_file = top / tree_rel
    if tree_file.exists():
        got = hashlib.sha256(tree_file.read_bytes()).hexdigest()
        if got != sha:
            sys.exit(f"{tree_rel} differs from the pinned stock {rel} ({got} != {sha}): "
                     "copy the stock file instead and resolve the install clash another way")
    return module


def parse_manifest(path):
    for raw in path.read_text(encoding="utf-8").splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        spec, _, sha = line.partition("|")
        rel, *flags = spec.split(";")
        yield rel, flags, sha


def module_name(stem, taken):
    name = re.sub(r"[^A-Za-z0-9_.+@-]", "_", stem)
    while name in taken:
        name += "_vantage"
    taken.add(name)
    return name


def main():
    if len(sys.argv) != 2:
        sys.exit(__doc__)
    vdir = Path(sys.argv[1])
    bp, packages, copies, taken = [HEADER], [], [], set()
    bp.append('soong_namespace {\n}\n')
    done = set()
    for rel, flags, sha in parse_manifest(vdir / "proprietary-files.txt"):
        if rel in done:  # a file may be required by more than one component
            continue
        done.add(rel)
        part, _, sub = rel.partition("/")
        flag = PART_FLAG.get(part)
        if flag is None:
            sys.exit(f"unsupported partition in manifest: {rel}")
        indent = f"    {flag}\n" if flag else ""
        src = f"proprietary/{rel}"
        fname = rel.rsplit("/", 1)[-1]
        symlink = next((f.split("=", 1)[1] for f in flags if f.startswith("SYMLINK=")), None)
        if symlink:
            name = module_name("symlink_" + sub.replace("/", "_"), taken)
            bp.append(
                f'install_symlink {{\n    name: "{name}",\n{indent}'
                f'    installed_location: "{sub}",\n    symlink_target: "{symlink}",\n}}\n'
            )
            packages.append(name)
        elif fname.endswith(".apk"):
            name = module_name(fname[:-4], taken)
            if "PRESIGNED" in flags:
                sign = "    presigned: true,\n    preprocessed: true,\n"
            else:
                cert = next((f.split("=", 1)[1] for f in flags if f.startswith("CERT=")), "platform")
                sign = f'    certificate: "{cert}",\n'
            priv = "    privileged: true,\n" if "PRIV" in flags else ""
            bp.append(
                f'android_app_import {{\n    name: "{name}",\n    owner: "{OWNER}",\n    apk: "{src}",\n'
                f'{sign}{priv}{indent}    dex_preopt: {{\n        enabled: false,\n    }},\n}}\n'
            )
            packages.append(name)
        elif fname.endswith(".jar"):
            name = module_name(fname[:-4], taken)
            bp.append(
                f'dex_import {{\n    name: "{name}",\n    owner: "{OWNER}",\n    jars: ["{src}"],\n{indent}'
                f'    prefer: true,\n}}\n'
            )
            packages.append(name)
        elif fname.endswith(".so") and "/lib64/" in f"/{sub}":
            name = module_name(fname[:-3], taken)
            bp.append(
                f'cc_prebuilt_library_shared {{\n    name: "{name}",\n    owner: "{OWNER}",\n'
                f'    stem: "{fname[:-3]}",\n    compile_multilib: "64",\n{indent}'
                f'    srcs: ["{src}"],\n    strip: {{\n        none: true,\n    }},\n'
                f'    check_elf_files: false,\n    prefer: true,\n}}\n'
            )
            packages.append(name)
        elif rel in NAMED_MODULES:
            name = module_name(NAMED_MODULES[rel], taken)
            subdir = sub.rsplit("/", 1)[0]
            sub_dir = subdir.split("/", 1)[1] if "/" in subdir else ""
            bp.append(
                f'prebuilt_etc {{\n    name: "{name}",\n    owner: "{OWNER}",\n    src: "{src}",\n'
                f'    filename: "{fname}",\n' + (f'    sub_dir: "{sub_dir}",\n' if sub_dir else "") +
                f'{indent}}}\n'
            )
            packages.append(name)
        else:
            module = tree_equivalent(vdir, rel, sha)
            if module:
                packages.append(module)
            else:
                copies.append(f"vendor/motorola/vantage/{src}:{COPY_OUT[part]}/{sub}")
    (vdir / "Android.bp").write_text("\n".join(bp), encoding="utf-8", newline="\n")

    mk = ["# Generated by scripts/setup_makefiles.py from proprietary-files.txt. Do not edit.", "",
          "PRODUCT_SOONG_NAMESPACES += vendor/motorola/vantage", ""]
    if packages:
        mk.append("PRODUCT_PACKAGES += \\")
        mk += [f"    {p} \\" for p in packages[:-1]] + [f"    {packages[-1]}", ""]
    if copies:
        mk.append("PRODUCT_COPY_FILES += \\")
        mk += [f"    {c} \\" for c in copies[:-1]] + [f"    {copies[-1]}", ""]
    (vdir / "vantage-vendor.mk").write_text("\n".join(mk), encoding="utf-8", newline="\n")
    print(f"{len(packages)} modules, {len(copies)} copied files")
    return 0


if __name__ == "__main__":
    sys.exit(main())
